import json
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
LOG = "/tmp/recon/events.log"

_token = None


def log(msg):
    with open(LOG, "a") as fh:
        fh.write(f"{time.strftime('%H:%M:%S')} {msg}\n")


def raw(method, path, token=None, timeout=30):
    """One HTTP call. Returns (status, headers_dict, body_text). Never raises on HTTP errors."""
    req = urllib.request.Request(BASE + path, method=method, data=b"" if method == "POST" else None)
    if token:
        req.add_header("Authorization", f"Bearer {token}")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.status, dict(resp.headers.items()), resp.read().decode("utf-8")
    except urllib.error.HTTPError as err:
        return err.code, dict(err.headers.items()), err.read().decode("utf-8")


def new_token():
    global _token
    status, headers, body = raw("POST", "/token")
    if status != 200:
        log(f"TOKEN FETCH FAILED {status} {headers} {body}")
        raise RuntimeError(f"token fetch failed: {status} {body}")
    _token = json.loads(body)["token"]
    log(f"new token {_token}")
    return _token


def retry_after_seconds(headers, body):
    """Wait time the service asked for, or None if it did not say."""
    for k, v in headers.items():
        if k.lower() == "retry-after":
            return float(v)
    try:
        data = json.loads(body)
    except ValueError:
        return None
    if isinstance(data, dict):
        for key in ("retry_after", "retry_after_seconds", "retry_after_s", "wait", "wait_seconds"):
            if key in data:
                return float(data[key])
    return None


def get(path, max_attempts=60):
    """Authenticated GET. Refreshes the token on expiry, waits out rate limits, retries 5xx.

    Returns (status, parsed_json_or_None). 404 is returned to the caller (unknown customer).
    Any response shape we do not recognise raises, so it can be looked at rather than guessed.
    """
    global _token
    if _token is None:
        new_token()
    for attempt in range(1, max_attempts + 1):
        status, headers, body = raw("GET", path, token=_token)
        if status == 200:
            return status, json.loads(body)
        log(f"{path} attempt {attempt}: {status} headers={headers} body={body[:500]}")
        if status == 401:
            new_token()
            continue
        if status == 429 or (status == 503 and retry_after_seconds(headers, body) is not None):
            wait = retry_after_seconds(headers, body)
            if wait is None:
                raise RuntimeError(f"{path}: {status} with no wait time given: {headers} {body}")
            log(f"{path}: waiting {wait}s as instructed")
            time.sleep(wait + 0.05)
            continue
        if status == 404:
            return status, json.loads(body) if body else None
        if 500 <= status < 600:
            time.sleep(min(2 ** (attempt - 1) * 0.25, 5))
            continue
        raise RuntimeError(f"{path}: unrecognised response {status} {headers} {body[:500]}")
    raise RuntimeError(f"{path}: gave up after {max_attempts} attempts")

